var AE_INVEST_READ_JS = '\n(function(){\n  var reads = {\n    "Dubai": {metric:"history:dubai-sale-psf", line:"Dubai heat: registered-sale AED/sqft where 20 or more sales support the area. Changing mix, not a constant-quality index, not a forecast."},\n    "Abu Dhabi": {metric:"price-psf", line:"Abu Dhabi heat: H1 2026 advertised asking AED/sqft on published localities only. Not registered sales; unmatched districts stay blank. ADREC H1 2026, whole emirate, not painted here: apartment repeat sales +20%, villas +12%; sales AED 70.4bn versus AED 25.3bn in H1 2025; stock about 409,000 homes. +71,000 homes by 2030 is the ADREC supply projection, not a price forecast. No monthly sale history is held."},\n    "Ajman": {metric:"history:unit-sales-count", line:"Ajman heat: official development-project unit sales counts. This is activity, not a price and not a yield."},\n    "Sharjah": {metric:"off", line:"Sharjah: 60 catalogue projects and 57 recorded asks. No local registered-sale series, so the heat stays off. Nothing is copied from Dubai or Ajman."},\n    "Ras Al Khaimah": {metric:"off", line:"Ras Al Khaimah: 89 catalogue projects and 77 recorded asks. No local registered-sale series, so the heat stays off."},\n    "Umm Al Quwain": {metric:"off", line:"Umm Al Quwain: 20 catalogue projects and 14 recorded asks. No local registered-sale series, so the heat stays off."},\n    "Fujairah": {metric:"off", line:"Fujairah: 1 catalogue project and 1 recorded ask. No local registered-sale series, so the heat stays off."}\n  };\n  function note(text){\n    var dock=document.querySelector("#tl-dock");\n    if(!dock) return;\n    var el=document.getElementById("ae-invest-read");\n    if(!el){\n      el=document.createElement("p");\n      el.id="ae-invest-read";\n      el.style.cssText="margin:0;font-size:10px;line-height:1.3;color:var(--ar-muted,#adbfd2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis";\n      dock.insertBefore(el, dock.firstChild);\n    }\n    el.textContent=text;\n    el.title=text;\n  }\n  function apply(name){\n    var choice=reads[name];\n    if(!choice) return;\n    var sel=document.querySelector("#analysis-metric");\n    if(choice.metric && sel && Array.prototype.some.call(sel.options, function(o){return o.value===choice.metric;})){\n      if(sel.value!==choice.metric){\n        sel.value=choice.metric;\n        sel.dispatchEvent(new Event("change",{bubbles:true}));\n      }\n    }\n    note(choice.line);\n  }\n  document.addEventListener("click", function(e){\n    var scope=e.target.closest && e.target.closest("[data-ae-scope]");\n    var row=e.target.closest && e.target.closest("[data-ae-emirate]");\n    var name=row?row.getAttribute("data-ae-emirate"):scope?scope.getAttribute("data-ae-scope"):"";\n    if(!name || name==="uae" || name==="more") return;\n    setTimeout(function(){apply(name);}, 60);\n  }, true);\n  note("Investment heat follows the emirate you open. Dubai prices are not copied into places without their own evidence.");\n})();\n';
