var EDR_PREVIOUS_FETCH = worker_default.fetch;
worker_default.fetch = async function(request, env, ctx) {
  const u = new URL(request.url), path = u.pathname.replace(/\/+$/, "");
  if (path === "/map/data-room" || path.startsWith("/map/data-room/")) {
    if (env.DATA_ROOM_PUBLIC !== "true") return new Response("Data room access has not been configured.", { status: 404, headers: { "cache-control": "no-store", "x-robots-tag": "noindex, nofollow" } });
    if (!["GET", "HEAD"].includes(request.method)) return new Response("Read-only research room", { status: 405, headers: { allow: "GET, HEAD" } });
    const key = path === "/map/data-room" ? "index.html" : path.slice("/map/data-room/".length), asset = EDR_ASSETS[key];
    if (!Object.hasOwn(EDR_ASSETS, key)) return new Response("Not found", { status: 404 });
    const headers = { "content-type": asset.type, "cache-control": "public, max-age=60", "etag": asset.etag, "x-content-type-options": "nosniff", "x-robots-tag": "noindex, nofollow", "referrer-policy": "same-origin", "content-security-policy": "default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; font-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'" };
    if (request.headers.get("if-none-match") === asset.etag) return new Response(null, { status: 304, headers });
    return new Response(request.method === "HEAD" ? null : asset.body, { headers });
  }
  return EDR_PREVIOUS_FETCH.call(this, request, env, ctx);
};

