var ESM_PREVIOUS_FETCH = worker_default.fetch;
worker_default.fetch = async function(request, env, ctx) {
  const u = new URL(request.url), path = u.pathname.replace(/\/+$/, "") || "/";
  if (path === "/map/api/system") {
    if (!["GET","HEAD"].includes(request.method)) return new Response("Method not allowed",{status:405,headers:{allow:"GET, HEAD"}});
    const body = JSON.stringify(esmSystemPayload(env), null, 2);
    return new Response(request.method === "HEAD" ? null : body,{headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","x-robots-tag":"noindex, nofollow"}});
  }
  if (path === "/map/system") {
    if (!["GET","HEAD"].includes(request.method)) return new Response("Method not allowed",{status:405,headers:{allow:"GET, HEAD"}});
    const body = esmSystemHtml(env);
    return new Response(request.method === "HEAD" ? null : body,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","x-robots-tag":"noindex, nofollow","referrer-policy":"same-origin"}});
  }
  const response = await ESM_PREVIOUS_FETCH.call(this, request, env, ctx);
  if ((path === "/map" || path === "/map/") && request.method === "GET" && (response.headers.get("content-type")||"").includes("text/html")) {
    let html = await response.text();
    if (!html.includes("ae-system-access-v1")) {
      const injection = '<style id="ae-system-access-v1">#ae-system-access{display:inline-flex;align-items:center;justify-content:center;height:38px;min-width:58px;padding:0 11px;border:1px solid rgba(103,196,239,.22);border-radius:11px;background:rgba(6,31,47,.80);color:#e3f4fb;text-decoration:none;font:700 9px/1 ui-sans-serif,system-ui;letter-spacing:.06em;text-transform:uppercase;white-space:nowrap}#ae-system-access:hover{background:rgba(12,61,88,.92)}@media(max-width:760px){#ae-system-access{height:36px;min-width:42px;padding:0 8px;font-size:8px}}</style><script>(function(){function add(){if(document.getElementById("ae-system-access"))return;var host=document.querySelector(".ae-search-map-tools")||document.querySelector(".topbar");if(!host)return;var a=document.createElement("a");a.id="ae-system-access";a.href="/map/system";a.textContent="System";a.setAttribute("aria-label","Open map system and Data Room access");host.appendChild(a)}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",add,{once:true});else add()})();<\/script>';
      html = html.replace("</head>", injection.split("<script>")[0]+"</head>").replace("</body>","<script>"+injection.split("<script>")[1]+"</body>");
    }
    const h = new Headers(response.headers); h.delete("content-length"); h.set("x-espacios-system", ESM_RELEASE);
    return new Response(html,{status:response.status,statusText:response.statusText,headers:h});
  }
  return response;
};



