/* Version only frontend responses. Original evidence endpoints and storage are unchanged. */
var MM_RELEASE='20261008-map-palette-v33';
var MM_PREVIOUS_FETCH=worker_default.fetch;
worker_default.fetch=async function(request,env,ctx){
 const response=await MM_PREVIOUS_FETCH.call(this,request,env,ctx);
 const path=new URL(request.url).pathname.replace(/\/+$/,'')||'/';
 if(!response.ok||!['/map','/map/app-v2.js','/map/app-v2.css'].includes(path))return response;
 const headers=new Headers(response.headers);headers.set('x-espacios-mobile',MM_RELEASE);
 if(headers.has('link'))headers.set('link',headers.get('link').replaceAll('20260930-smart-estimates-v1',MM_RELEASE).replaceAll('20261008-map-palette-v23',MM_RELEASE).replaceAll('20261008-map-palette-v24',MM_RELEASE));
 for(const name of ['x-ae-navigation','x-psr-map-navfix'])if(headers.has(name))headers.set(name,MM_RELEASE);
 if(path==='/map'&&request.method==='GET'){
  const html=(await response.text()).replaceAll('20260930-smart-estimates-v1',MM_RELEASE).replaceAll('20261008-map-palette-v23',MM_RELEASE).replaceAll('20261008-map-palette-v24',MM_RELEASE);
  headers.delete('content-length');headers.delete('etag');return new Response(html,{status:response.status,headers});
 }
 if(path==='/map/app-v2.js'&&request.method==='GET'){
  const javascript=(await response.text()).replaceAll('/map/map-core.json?v=20260929-collapse-repair-v3','/map/map-core.json?v='+MM_RELEASE).replaceAll('/map/map-data.json?v=20260929-collapse-repair-v3','/map/map-data.json?v='+MM_RELEASE).replaceAll('/map/api/projects-batch?','/map/api/projects-batch?review='+MM_RELEASE+'&').replaceAll('/map/api/projects-all','/map/api/projects-all?review='+MM_RELEASE).replaceAll('20261008-map-palette-v23',MM_RELEASE).replaceAll('20261008-map-palette-v24',MM_RELEASE);
  headers.delete('content-length');headers.delete('etag');return new Response(javascript,{status:response.status,headers});
 }
 return new Response(response.body,{status:response.status,headers});
};

/* Cloudflare <-> Supabase read-only control plane. Market evidence remains in D1/R2. */
var MAP_CONTROL_RELEASE='20261003-supabase-control-v1';
var MAP_CONTROL_PREVIOUS_FETCH=worker_default.fetch;

async function mapControlRead(env){
  const endpoint=String(env.SUPABASE_CONTROL_URL||'');
  if(!endpoint)return {connected:false,error:'Supabase control endpoint binding unavailable'};
  const response=await fetch(endpoint,{headers:{accept:'application/json'}});
  if(!response.ok)return {connected:false,error:'Supabase control plane unavailable',status:response.status};
  const payload=await response.json();
  return {
    ...payload,
    release:MAP_CONTROL_RELEASE,
    authority:{
      runtime:'Cloudflare Workers',
      source:'GitHub gugmaae-prog/espacios',
      controlAudit:'Supabase',
      marketEvidence:'Cloudflare D1/R2 + PSR_PROPERTY'
    }
  };
}

worker_default.fetch=async function(request,env,ctx){
  const u=new URL(request.url),path=u.pathname.replace(/\/+$/,'')||'/';
  if(path==='/map/api/control-plane'){
    if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405,headers:{allow:'GET, HEAD'}});
    let payload;
    try{payload=await mapControlRead(env);}catch(error){payload={connected:false,error:'Supabase control plane request failed'};}
    const body=JSON.stringify(payload,null,2);
    return new Response(request.method==='HEAD'?null:body,{status:payload.connected?200:503,headers:{
      'content-type':'application/json; charset=utf-8',
      'cache-control':'no-store',
      'x-content-type-options':'nosniff',
      'x-robots-tag':'noindex, nofollow',
      'x-espacios-control':MAP_CONTROL_RELEASE
    }});
  }
  const response=await MAP_CONTROL_PREVIOUS_FETCH.call(this,request,env,ctx);
  if(path==='/map/api/system'&&request.method==='GET'&&response.ok){
    let payload;
    try{payload=await response.json();}catch{return response;}
    let control;
    try{control=await mapControlRead(env);}catch{control={connected:false,error:'Supabase control plane request failed'};}
    payload.controlPlane=control;
    const headers=new Headers(response.headers);headers.set('cache-control','no-store');headers.delete('content-length');headers.delete('etag');
    return new Response(JSON.stringify(payload,null,2),{status:response.status,headers});
  }
  return response;
};

/* Preserve PSR tenant boundary. Espacios map/system stays unavailable on psrhomes.ae. */
var PSR_TENANT_GUARD_RELEASE='20261002-psr-map-tenant-guard-v1';
var PSR_TENANT_GUARD_PREVIOUS_FETCH=worker_default.fetch;
worker_default.fetch=async function(request,env,ctx){
  const u=new URL(request.url),path=u.pathname.replace(/\/+$/,'')||'/';
  const psrHost=u.hostname==='psrhomes.ae'||u.hostname==='www.psrhomes.ae';
  if(psrHost&&(path==='/map'||path==='/map/system'||path==='/map/api/system'||path==='/map/api/control-plane')){
    const common={'cache-control':'no-store','x-robots-tag':'noindex, nofollow','x-content-type-options':'nosniff','x-psr-cache-key':'psr-map-tenant-block-20261002-v1'};
    if(path.startsWith('/map/api/'))return new Response(JSON.stringify({error:'Not found',product:'PSR Homes'}),{status:404,headers:{...common,'content-type':'application/json; charset=utf-8'}});
    const html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Not found | PSR Homes</title></head><body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#111715;color:#f5f1e8;font-family:Arial,sans-serif"><main style="max-width:620px;padding:40px;text-align:center"><h1 style="font-weight:400;font-size:36px">This page is not available.</h1><p style="color:#b9b2a8;line-height:1.7">Return to PSR Homes to explore current properties, communities and market research.</p><a href="/" style="color:#f5f1e8">PSR Homes</a></main></body></html>';
    return new Response(html,{status:404,headers:{...common,'content-type':'text/html; charset=utf-8'}});
  }
  return PSR_TENANT_GUARD_PREVIOUS_FETCH.call(this,request,env,ctx);
};

export {worker_default as default};
